INSERT INTO drills (id, name, description, focus, equipment, age_group, pitch_size, players_required, duration_minutes, coaching_points, progression, regression, owner_user_id, visibility, is_official, tags) VALUES (
  '77e4d298-1c2c-406f-b0e9-a62185f8f187',
  'Piggy in the middle',
  'Classic 3-player keep-ball. Two outside players keep possession from a defender (the ''piggy'') in a small grid. When piggy intercepts or forces a bad touch, swap roles.',
  ARRAY['passing','possession','first-touch'],
  ARRAY['1 ball per group','4 cones per grid'],
  'U7+',
  'small',
  3,
  8,
  ARRAY['Open body shape before receiving','First touch away from the piggy','Disguise the pass — look one way, play another','Move to support after every pass'],
  'Limit to two touches, then one. Add a second piggy.',
  'Make the grid bigger or allow unlimited touches.',
  '00000000-0000-0000-0000-000000000000',
  'official',
  true,
  ARRAY[]::text[]
);
INSERT INTO drill_frames (drill_id, position, duration_ms, notes, objects, annotations) VALUES ('77e4d298-1c2c-406f-b0e9-a62185f8f187', 0, 2400, 'Setup — 10x10m grid with 4 cones. A1 and A2 outside, defender (the ''piggy'') in the middle. Ball starts with A1.', $JSON$[{"id": "c1", "type": "cone", "x": 25, "y": 30, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c2", "type": "cone", "x": 75, "y": 30, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c3", "type": "cone", "x": 25, "y": 70, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c4", "type": "cone", "x": 75, "y": 70, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "a1", "type": "player", "x": 35, "y": 50, "label": "1", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "a2", "type": "player", "x": 65, "y": 50, "label": "2", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "d1", "type": "player", "x": 50, "y": 50, "label": "P", "color": "#ef4444", "rotation": 0, "size": 1}, {"id": "b1", "type": "ball", "x": 35, "y": 50, "color": "#f5f5f5", "rotation": 0, "size": 1}]$JSON$::jsonb, $JSON$[{"id": "t1", "type": "text", "geometry": {"x": 50, "y": 22, "text": "10x10m grid"}}]$JSON$::jsonb);
INSERT INTO drill_frames (drill_id, position, duration_ms, notes, objects, annotations) VALUES ('77e4d298-1c2c-406f-b0e9-a62185f8f187', 1, 2400, 'Frame 1 — A1 plays a firm, low pass past the piggy to A2.', $JSON$[{"id": "c1", "type": "cone", "x": 25, "y": 30, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c2", "type": "cone", "x": 75, "y": 30, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c3", "type": "cone", "x": 25, "y": 70, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c4", "type": "cone", "x": 75, "y": 70, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "a1", "type": "player", "x": 35, "y": 50, "label": "1", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "a2", "type": "player", "x": 65, "y": 50, "label": "2", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "d1", "type": "player", "x": 50, "y": 50, "label": "P", "color": "#ef4444", "rotation": 0, "size": 1}, {"id": "b1", "type": "ball", "x": 50, "y": 50, "color": "#f5f5f5", "rotation": 0, "size": 1}]$JSON$::jsonb, $JSON$[{"id": "a1", "type": "arrow-solid", "geometry": {"from": {"x": 38, "y": 50}, "to": {"x": 62, "y": 50}}, "style": {"color": "#fbbf24"}}]$JSON$::jsonb);
INSERT INTO drill_frames (drill_id, position, duration_ms, notes, objects, annotations) VALUES ('77e4d298-1c2c-406f-b0e9-a62185f8f187', 2, 2400, 'Frame 2 — A2 takes a touch away from the piggy. A1 moves to a new angle so A2 always has a passing option.', $JSON$[{"id": "c1", "type": "cone", "x": 25, "y": 30, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c2", "type": "cone", "x": 75, "y": 30, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c3", "type": "cone", "x": 25, "y": 70, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c4", "type": "cone", "x": 75, "y": 70, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "a1", "type": "player", "x": 35, "y": 60, "label": "1", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "a2", "type": "player", "x": 65, "y": 50, "label": "2", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "d1", "type": "player", "x": 58, "y": 50, "label": "P", "color": "#ef4444", "rotation": 0, "size": 1}, {"id": "b1", "type": "ball", "x": 65, "y": 50, "color": "#f5f5f5", "rotation": 0, "size": 1}]$JSON$::jsonb, $JSON$[{"id": "a1", "type": "arrow-solid", "geometry": {"from": {"x": 50, "y": 50}, "to": {"x": 56, "y": 50}}, "style": {"color": "#ef4444"}}, {"id": "t1", "type": "text", "geometry": {"x": 35, "y": 70, "text": "A1 shifts to support"}}]$JSON$::jsonb);
INSERT INTO drill_frames (drill_id, position, duration_ms, notes, objects, annotations) VALUES ('77e4d298-1c2c-406f-b0e9-a62185f8f187', 3, 2400, 'Frame 3 — A2 disguises and slides the ball back to A1 in space. Pass and follow.', $JSON$[{"id": "c1", "type": "cone", "x": 25, "y": 30, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c2", "type": "cone", "x": 75, "y": 30, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c3", "type": "cone", "x": 25, "y": 70, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c4", "type": "cone", "x": 75, "y": 70, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "a1", "type": "player", "x": 35, "y": 65, "label": "1", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "a2", "type": "player", "x": 65, "y": 50, "label": "2", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "d1", "type": "player", "x": 60, "y": 50, "label": "P", "color": "#ef4444", "rotation": 0, "size": 1}, {"id": "b1", "type": "ball", "x": 36, "y": 65, "color": "#f5f5f5", "rotation": 0, "size": 1}]$JSON$::jsonb, $JSON$[{"id": "a1", "type": "arrow-solid", "geometry": {"from": {"x": 65, "y": 50}, "to": {"x": 36, "y": 65}}, "style": {"color": "#fbbf24"}}]$JSON$::jsonb);
INSERT INTO drill_frames (drill_id, position, duration_ms, notes, objects, annotations) VALUES ('77e4d298-1c2c-406f-b0e9-a62185f8f187', 4, 2400, 'Frame 4 — If the piggy intercepts or forces a bad touch out of the grid, the player responsible becomes the new piggy.', $JSON$[{"id": "c1", "type": "cone", "x": 25, "y": 30, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c2", "type": "cone", "x": 75, "y": 30, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c3", "type": "cone", "x": 25, "y": 70, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c4", "type": "cone", "x": 75, "y": 70, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "a1", "type": "player", "x": 35, "y": 65, "label": "1", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "a2", "type": "player", "x": 65, "y": 60, "label": "2", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "d1", "type": "player", "x": 50, "y": 60, "label": "P", "color": "#ef4444", "rotation": 0, "size": 1}, {"id": "b1", "type": "ball", "x": 50, "y": 60, "color": "#f5f5f5", "rotation": 0, "size": 1}]$JSON$::jsonb, $JSON$[{"id": "t1", "type": "text", "geometry": {"x": 50, "y": 25, "text": "Swap roles when piggy wins it"}}]$JSON$::jsonb);
INSERT INTO drills (id, name, description, focus, equipment, age_group, pitch_size, players_required, duration_minutes, coaching_points, progression, regression, owner_user_id, visibility, is_official, tags) VALUES (
  'b244be9f-7dfb-4470-87a1-868a83456d27',
  'Traffic lights warm-up',
  'Whole-group ball-mastery warm-up. Coach calls colours: GREEN = dribble fast, AMBER = slow rolls / turns, RED = stop with sole on ball. Develops ball control under instruction.',
  ARRAY['warm-up','ball-mastery','listening'],
  ARRAY['1 ball per player','Cones to mark grid'],
  'U6-U10',
  'small',
  8,
  6,
  ARRAY['Head up to hear and see the coach','Small touches when red — sole of foot on ball','Use both feet on green','Change direction on amber, never lose the ball'],
  'Add commands: BLUE = backwards, YELLOW = turn 360°. Faster call cadence.',
  'Walking pace only; just GREEN and RED to start.',
  '00000000-0000-0000-0000-000000000000',
  'official',
  true,
  ARRAY[]::text[]
);
INSERT INTO drill_frames (drill_id, position, duration_ms, notes, objects, annotations) VALUES ('b244be9f-7dfb-4470-87a1-868a83456d27', 0, 2400, 'Setup — every player has a ball inside a 20x20m grid. Coach stands on one edge and calls colours.', $JSON$[{"id": "c1", "type": "cone", "x": 20, "y": 20, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c2", "type": "cone", "x": 80, "y": 20, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c3", "type": "cone", "x": 20, "y": 80, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c4", "type": "cone", "x": 80, "y": 80, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "p1", "type": "player", "x": 32, "y": 32, "label": "1", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "b1", "type": "ball", "x": 32, "y": 32, "color": "#f5f5f5", "rotation": 0, "size": 1}, {"id": "p2", "type": "player", "x": 50, "y": 30, "label": "2", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "b2", "type": "ball", "x": 50, "y": 30, "color": "#f5f5f5", "rotation": 0, "size": 1}, {"id": "p3", "type": "player", "x": 68, "y": 35, "label": "3", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "b3", "type": "ball", "x": 68, "y": 35, "color": "#f5f5f5", "rotation": 0, "size": 1}, {"id": "p4", "type": "player", "x": 35, "y": 55, "label": "4", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "b4", "type": "ball", "x": 35, "y": 55, "color": "#f5f5f5", "rotation": 0, "size": 1}, {"id": "p5", "type": "player", "x": 55, "y": 55, "label": "5", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "b5", "type": "ball", "x": 55, "y": 55, "color": "#f5f5f5", "rotation": 0, "size": 1}, {"id": "p6", "type": "player", "x": 70, "y": 60, "label": "6", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "b6", "type": "ball", "x": 70, "y": 60, "color": "#f5f5f5", "rotation": 0, "size": 1}, {"id": "c", "type": "player", "x": 50, "y": 12, "label": "Coach", "color": "#22c55e", "rotation": 0, "size": 1}]$JSON$::jsonb, $JSON$[{"id": "t1", "type": "text", "geometry": {"x": 50, "y": 86, "text": "Coach calls a colour"}}]$JSON$::jsonb);
INSERT INTO drill_frames (drill_id, position, duration_ms, notes, objects, annotations) VALUES ('b244be9f-7dfb-4470-87a1-868a83456d27', 1, 2400, 'GREEN — players dribble at speed in any direction. Heads up so they don''t crash. Use both feet.', $JSON$[{"id": "c1", "type": "cone", "x": 20, "y": 20, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c2", "type": "cone", "x": 80, "y": 20, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c3", "type": "cone", "x": 20, "y": 80, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c4", "type": "cone", "x": 80, "y": 80, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "p1", "type": "player", "x": 40, "y": 40, "label": "1", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "b1", "type": "ball", "x": 40, "y": 40, "color": "#f5f5f5", "rotation": 0, "size": 1}, {"id": "p2", "type": "player", "x": 60, "y": 35, "label": "2", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "b2", "type": "ball", "x": 60, "y": 35, "color": "#f5f5f5", "rotation": 0, "size": 1}, {"id": "p3", "type": "player", "x": 75, "y": 50, "label": "3", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "b3", "type": "ball", "x": 75, "y": 50, "color": "#f5f5f5", "rotation": 0, "size": 1}, {"id": "p4", "type": "player", "x": 28, "y": 65, "label": "4", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "b4", "type": "ball", "x": 28, "y": 65, "color": "#f5f5f5", "rotation": 0, "size": 1}, {"id": "p5", "type": "player", "x": 50, "y": 70, "label": "5", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "b5", "type": "ball", "x": 50, "y": 70, "color": "#f5f5f5", "rotation": 0, "size": 1}, {"id": "p6", "type": "player", "x": 65, "y": 70, "label": "6", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "b6", "type": "ball", "x": 65, "y": 70, "color": "#f5f5f5", "rotation": 0, "size": 1}, {"id": "c", "type": "player", "x": 50, "y": 12, "label": "GREEN", "color": "#22c55e", "rotation": 0, "size": 1}]$JSON$::jsonb, $JSON$[{"id": "a1", "type": "arrow-solid", "geometry": {"from": {"x": 32, "y": 32}, "to": {"x": 40, "y": 40}}, "style": {"color": "#fbbf24"}}, {"id": "a2", "type": "arrow-solid", "geometry": {"from": {"x": 50, "y": 30}, "to": {"x": 60, "y": 35}}, "style": {"color": "#fbbf24"}}, {"id": "a3", "type": "arrow-solid", "geometry": {"from": {"x": 68, "y": 35}, "to": {"x": 75, "y": 50}}, "style": {"color": "#fbbf24"}}, {"id": "t1", "type": "text", "geometry": {"x": 50, "y": 86, "text": "GREEN — dribble at speed"}}]$JSON$::jsonb);
INSERT INTO drill_frames (drill_id, position, duration_ms, notes, objects, annotations) VALUES ('b244be9f-7dfb-4470-87a1-868a83456d27', 2, 2400, 'AMBER — slow down. Players use sole rolls and turns (drag-back, inside / outside hook).', $JSON$[{"id": "c1", "type": "cone", "x": 20, "y": 20, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c2", "type": "cone", "x": 80, "y": 20, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c3", "type": "cone", "x": 20, "y": 80, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c4", "type": "cone", "x": 80, "y": 80, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "p1", "type": "player", "x": 38, "y": 42, "label": "1", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "b1", "type": "ball", "x": 38, "y": 42, "color": "#f5f5f5", "rotation": 0, "size": 1}, {"id": "p2", "type": "player", "x": 62, "y": 38, "label": "2", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "b2", "type": "ball", "x": 62, "y": 38, "color": "#f5f5f5", "rotation": 0, "size": 1}, {"id": "p3", "type": "player", "x": 72, "y": 52, "label": "3", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "b3", "type": "ball", "x": 72, "y": 52, "color": "#f5f5f5", "rotation": 0, "size": 1}, {"id": "p4", "type": "player", "x": 30, "y": 62, "label": "4", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "b4", "type": "ball", "x": 30, "y": 62, "color": "#f5f5f5", "rotation": 0, "size": 1}, {"id": "p5", "type": "player", "x": 52, "y": 68, "label": "5", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "b5", "type": "ball", "x": 52, "y": 68, "color": "#f5f5f5", "rotation": 0, "size": 1}, {"id": "p6", "type": "player", "x": 64, "y": 68, "label": "6", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "b6", "type": "ball", "x": 64, "y": 68, "color": "#f5f5f5", "rotation": 0, "size": 1}, {"id": "c", "type": "player", "x": 50, "y": 12, "label": "AMBER", "color": "#f59e0b", "rotation": 0, "size": 1}]$JSON$::jsonb, $JSON$[{"id": "t1", "type": "text", "geometry": {"x": 50, "y": 86, "text": "AMBER — slow + turns"}}, {"id": "t2", "type": "text", "geometry": {"x": 50, "y": 80, "text": "Drag-back, inside hook, outside hook"}}]$JSON$::jsonb);
INSERT INTO drill_frames (drill_id, position, duration_ms, notes, objects, annotations) VALUES ('b244be9f-7dfb-4470-87a1-868a83456d27', 3, 2400, 'RED — everyone stops dead with the sole of the foot on top of the ball. Coach can add a fun forfeit for the last to react.', $JSON$[{"id": "c1", "type": "cone", "x": 20, "y": 20, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c2", "type": "cone", "x": 80, "y": 20, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c3", "type": "cone", "x": 20, "y": 80, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c4", "type": "cone", "x": 80, "y": 80, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "p1", "type": "player", "x": 38, "y": 42, "label": "1", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "b1", "type": "ball", "x": 38, "y": 42, "color": "#f5f5f5", "rotation": 0, "size": 1}, {"id": "p2", "type": "player", "x": 62, "y": 38, "label": "2", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "b2", "type": "ball", "x": 62, "y": 38, "color": "#f5f5f5", "rotation": 0, "size": 1}, {"id": "p3", "type": "player", "x": 72, "y": 52, "label": "3", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "b3", "type": "ball", "x": 72, "y": 52, "color": "#f5f5f5", "rotation": 0, "size": 1}, {"id": "p4", "type": "player", "x": 30, "y": 62, "label": "4", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "b4", "type": "ball", "x": 30, "y": 62, "color": "#f5f5f5", "rotation": 0, "size": 1}, {"id": "p5", "type": "player", "x": 52, "y": 68, "label": "5", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "b5", "type": "ball", "x": 52, "y": 68, "color": "#f5f5f5", "rotation": 0, "size": 1}, {"id": "p6", "type": "player", "x": 64, "y": 68, "label": "6", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "b6", "type": "ball", "x": 64, "y": 68, "color": "#f5f5f5", "rotation": 0, "size": 1}, {"id": "c", "type": "player", "x": 50, "y": 12, "label": "RED", "color": "#ef4444", "rotation": 0, "size": 1}]$JSON$::json