INSERT INTO drills (id, name, description, focus, equipment, age_group, pitch_size, players_required, duration_minutes, coaching_points, progression, regression, owner_user_id, visibility, is_official, tags) VALUES (
  'bc5ca411-17f4-45c0-928f-b10efebb628f',
  'Throw-in basics & receive',
  'Sideline throw-in technique with a target receiver. Thrower drills the legal technique (both feet on/behind line, ball over head with two hands). Receivers practise checking-away to feet or run-in behind.',
  ARRAY['set-pieces','throw-ins','movement'],
  ARRAY['2 balls','4 cones to mark sideline'],
  'U9+',
  'half',
  4,
  10,
  ARRAY['Both hands on the ball, taken from behind and over the head','Both feet on the ground, on or behind the touchline','Throw to feet or into space — never aimlessly','Receiver: check away, then come short or spin in behind'],
  'Add a defender on the receiver. Add a third option (short return throw to thrower).',
  'Static receiver, no defender, focus on legal technique only.',
  '00000000-0000-0000-0000-000000000000',
  'official',
  true,
  ARRAY[]::text[]
);
INSERT INTO drill_frames (drill_id, position, duration_ms, notes, objects, annotations) VALUES ('bc5ca411-17f4-45c0-928f-b10efebb628f', 0, 2400, 'Setup — Thrower (T) on the touchline with the ball. Two receivers (R1 short, R2 deeper) and one defender.', $JSON$[{"id": "c1", "type": "cone", "x": 8, "y": 30, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c2", "type": "cone", "x": 8, "y": 70, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "th", "type": "player", "x": 8, "y": 50, "label": "T", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "b1", "type": "ball", "x": 8, "y": 50, "color": "#f5f5f5", "rotation": 0, "size": 1}, {"id": "r1", "type": "player", "x": 30, "y": 35, "label": "R1", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "r2", "type": "player", "x": 35, "y": 65, "label": "R2", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "d1", "type": "player", "x": 45, "y": 50, "label": "D", "color": "#ef4444", "rotation": 0, "size": 1}]$JSON$::jsonb, $JSON$[{"id": "t1", "type": "text", "geometry": {"x": 8, "y": 22, "text": "Sideline"}}, {"id": "t2", "type": "text", "geometry": {"x": 50, "y": 12, "text": "Throw-in setup"}}]$JSON$::jsonb);
INSERT INTO drill_frames (drill_id, position, duration_ms, notes, objects, annotations) VALUES ('bc5ca411-17f4-45c0-928f-b10efebb628f', 1, 2400, 'Frame 1 — R1 checks away then comes short. Thrower delivers to R1''s feet. Both feet stay on the ground.', $JSON$[{"id": "c1", "type": "cone", "x": 8, "y": 30, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c2", "type": "cone", "x": 8, "y": 70, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "th", "type": "player", "x": 8, "y": 50, "label": "T", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "r1", "type": "player", "x": 25, "y": 40, "label": "R1", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "r2", "type": "player", "x": 35, "y": 65, "label": "R2", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "d1", "type": "player", "x": 45, "y": 50, "label": "D", "color": "#ef4444", "rotation": 0, "size": 1}, {"id": "b1", "type": "ball", "x": 12, "y": 45, "color": "#f5f5f5", "rotation": 0, "size": 1}]$JSON$::jsonb, $JSON$[{"id": "a1", "type": "arrow-solid", "geometry": {"from": {"x": 8, "y": 50}, "to": {"x": 25, "y": 40}}, "style": {"color": "#fbbf24"}}, {"id": "t1", "type": "text", "geometry": {"x": 50, "y": 86, "text": "Both feet down, ball over head"}}]$JSON$::jsonb);
INSERT INTO drill_frames (drill_id, position, duration_ms, notes, objects, annotations) VALUES ('bc5ca411-17f4-45c0-928f-b10efebb628f', 2, 2400, 'Frame 2 — R1''s first touch sets the ball back to T who has stepped in onto the pitch.', $JSON$[{"id": "c1", "type": "cone", "x": 8, "y": 30, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c2", "type": "cone", "x": 8, "y": 70, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "th", "type": "player", "x": 12, "y": 55, "label": "T", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "r1", "type": "player", "x": 25, "y": 40, "label": "R1", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "r2", "type": "player", "x": 35, "y": 65, "label": "R2", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "d1", "type": "player", "x": 45, "y": 50, "label": "D", "color": "#ef4444", "rotation": 0, "size": 1}, {"id": "b1", "type": "ball", "x": 18, "y": 50, "color": "#f5f5f5", "rotation": 0, "size": 1}]$JSON$::jsonb, $JSON$[{"id": "a1", "type": "arrow-solid", "geometry": {"from": {"x": 25, "y": 40}, "to": {"x": 18, "y": 50}}, "style": {"color": "#fbbf24"}}, {"id": "t1", "type": "text", "geometry": {"x": 50, "y": 86, "text": "First touch sets back to thrower stepping in"}}]$JSON$::jsonb);
INSERT INTO drill_frames (drill_id, position, duration_ms, notes, objects, annotations) VALUES ('bc5ca411-17f4-45c0-928f-b10efebb628f', 3, 2400, 'Frame 3 — Alternative: R2 spins in behind the defender. Thrower picks the long option into space, R2 runs onto it.', $JSON$[{"id": "c1", "type": "cone", "x": 8, "y": 30, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c2", "type": "cone", "x": 8, "y": 70, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "th", "type": "player", "x": 8, "y": 50, "label": "T", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "r1", "type": "player", "x": 28, "y": 40, "label": "R1", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "r2", "type": "player", "x": 55, "y": 70, "label": "R2", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "d1", "type": "player", "x": 45, "y": 55, "label": "D", "color": "#ef4444", "rotation": 0, "size": 1}, {"id": "b1", "type": "ball", "x": 35, "y": 60, "color": "#f5f5f5", "rotation": 0, "size": 1}]$JSON$::jsonb, $JSON$[{"id": "a1", "type": "arrow-solid", "geometry": {"from": {"x": 8, "y": 50}, "to": {"x": 55, "y": 70}}, "style": {"color": "#fbbf24"}}, {"id": "a2", "type": "arrow-solid", "geometry": {"from": {"x": 35, "y": 65}, "to": {"x": 55, "y": 70}}, "style": {"color": "#0ea5e9"}}, {"id": "t1", "type": "text", "geometry": {"x": 50, "y": 14, "text": "Spin in behind on coach''s call"}}]$JSON$::jsonb);
INSERT INTO drill_frames (drill_id, position, duration_ms, notes, objects, annotations) VALUES ('bc5ca411-17f4-45c0-928f-b10efebb628f', 4, 2400, 'Coaching cue — Decide which receiver to use BEFORE picking up the ball. Foul throws (foot lifted, one hand) hand possession to the opposition.', $JSON$[{"id": "c1", "type": "cone", "x": 8, "y": 30, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c2", "type": "cone", "x": 8, "y": 70, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "th", "type": "player", "x": 8, "y": 50, "label": "T", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "b1", "type": "ball", "x": 8, "y": 50, "color": "#f5f5f5", "rotation": 0, "size": 1}, {"id": "r1", "type": "player", "x": 25, "y": 40, "label": "R1", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "r2", "type": "player", "x": 35, "y": 65, "label": "R2", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "d1", "type": "player", "x": 45, "y": 50, "label": "D", "color": "#ef4444", "rotation": 0, "size": 1}]$JSON$::jsonb, $JSON$[{"id": "t1", "type": "text", "geometry": {"x": 50, "y": 14, "text": "Decide BEFORE you pick up the ball"}}, {"id": "t2", "type": "text", "geometry": {"x": 50, "y": 86, "text": "Foul throw = turnover"}}]$JSON$::jsonb);
INSERT INTO drills (id, name, description, focus, equipment, age_group, pitch_size, players_required, duration_minutes, coaching_points, progression, regression, owner_user_id, visibility, is_official, tags) VALUES (
  '2a26d6fc-934b-41e8-b44a-6bd14731e73f',
  'GK handling & footwork',
  'Goalkeeper repetition drill. Server feeds the keeper from a cone arc — low, mid, and high serves. Keeper uses small steps to set, takes the ball cleanly, and resets between each rep.',
  ARRAY['goalkeeping','handling','footwork'],
  ARRAY['6 balls','5 cones (server arc)','1 full goal'],
  'U10+',
  'half',
  2,
  12,
  ARRAY['Set position before each save — small steps, knees bent','Hands form a ''W'' on chest+ saves, ''scoop'' on low','Eyes through the ball to the catch','Reset to centre of goal between reps'],
  'Server adds a bounce. Add a striker who can finish any spill.',
  'Static feeds at chest height only. Slower cadence.',
  '00000000-0000-0000-0000-000000000000',
  'official',
  true,
  ARRAY[]::text[]
);
INSERT INTO drill_frames (drill_id, position, duration_ms, notes, objects, annotations) VALUES ('2a26d6fc-934b-41e8-b44a-6bd14731e73f', 0, 2400, 'Setup — full goal, GK on the line. Server (S) has 6 balls behind a cone arc 35-40m out. Each cone is a serving station.', $JSON$[{"id": "g1", "type": "goal-full", "x": 50, "y": 8, "color": "#ffffff", "rotation": 0, "size": 1}, {"id": "gk", "type": "player", "x": 50, "y": 18, "label": "GK", "color": "#22c55e", "rotation": 0, "size": 1}, {"id": "s", "type": "player", "x": 50, "y": 60, "label": "S", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "c1", "type": "cone", "x": 30, "y": 50, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c2", "type": "cone", "x": 40, "y": 50, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c3", "type": "cone", "x": 50, "y": 50, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c4", "type": "cone", "x": 60, "y": 50, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c5", "type": "cone", "x": 70, "y": 50, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "b1", "type": "ball", "x": 47, "y": 60, "color": "#f5f5f5", "rotation": 0, "size": 1}, {"id": "b2", "type": "ball", "x": 50, "y": 60, "color": "#f5f5f5", "rotation": 0, "size": 1}, {"id": "b3", "type": "ball", "x": 53, "y": 60, "color": "#f5f5f5", "rotation": 0, "size": 1}]$JSON$::jsonb, $JSON$[{"id": "t1", "type": "text", "geometry": {"x": 50, "y": 88, "text": "Server arc — 5 stations"}}]$JSON$::jsonb);
INSERT INTO drill_frames (drill_id, position, duration_ms, notes, objects, annotations) VALUES ('2a26d6fc-934b-41e8-b44a-6bd14731e73f', 1, 2400, 'Frame 1 — Low serve to GK''s right. GK shuffles across, drops to long-barrier position, scoops with both hands.', $JSON$[{"id": "g1", "type": "goal-full", "x": 50, "y": 8, "color": "#ffffff", "rotation": 0, "size": 1}, {"id": "gk", "type": "player", "x": 56, "y": 18, "label": "GK", "color": "#22c55e", "rotation": 0, "size": 1}, {"id": "s", "type": "player", "x": 60, "y": 55, "label": "S", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "c1", "type": "cone", "x": 30, "y": 50, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c2", "type": "cone", "x": 40, "y": 50, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c3", "type": "cone", "x": 50, "y": 50, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c4", "type": "cone", "x": 60, "y": 50, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c5", "type": "cone", "x": 70, "y": 50, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "b1", "type": "ball", "x": 58, "y": 22, "color": "#f5f5f5", "rotation": 0, "size": 1}]$JSON$::jsonb, $JSON$[{"id": "a1", "type": "arrow-solid", "geometry": {"from": {"x": 60, "y": 55}, "to": {"x": 58, "y": 22}}, "style": {"color": "#fbbf24"}}, {"id": "t1", "type": "text", "geometry": {"x": 50, "y": 88, "text": "Low scoop — long barrier"}}]$JSON$::jsonb);
INSERT INTO drill_frames (drill_id, position, duration_ms, notes, objects, annotations) VALUES ('2a26d6fc-934b-41e8-b44a-6bd14731e73f', 2, 2400, 'Frame 2 — Chest-height serve. GK steps in, hands form a ''W'' behind the ball, cushions into the chest.', $JSON$[{"id": "g1", "type": "goal-full", "x": 50, "y": 8, "color": "#ffffff", "rotation": 0, "size": 1}, {"id": "gk", "type": "player", "x": 50, "y": 18, "label": "GK", "color": "#22c55e", "rotation": 0, "size": 1}, {"id": "s", "type": "player", "x": 50, "y": 55, "label": "S", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "c1", "type": "cone", "x": 30, "y": 50, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c2", "type": "cone", "x": 40, "y": 50, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c3", "type": "cone", "x": 50, "y": 50, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c4", "type": "cone", "x": 60, "y": 50, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c5", "type": "cone", "x": 70, "y": 50, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "b1", "type": "ball", "x": 50, "y": 25, "color": "#f5f5f5", "rotation": 0, "size": 1}]$JSON$::jsonb, $JSON$[{"id": "a1", "type": "arrow-solid", "geometry": {"from": {"x": 50, "y": 55}, "to": {"x": 50, "y": 25}}, "style": {"color": "#fbbf24"}}, {"id": "t1", "type": "text", "geometry": {"x": 50, "y": 88, "text": "W-shape on the catch"}}]$JSON$::jsonb);
INSERT INTO drill_frames (drill_id, position, duration_ms, notes, objects, annotations) VALUES ('2a26d6fc-934b-41e8-b44a-6bd14731e73f', 3, 2400, 'Frame 3 — High serve to GK''s left. GK takes off the dominant foot and catches the ball at the highest reachable point.', $JSON$[{"id": "g1", "type": "goal-full", "x": 50, "y": 8, "color": "#ffffff", "rotation": 0, "size": 1}, {"id": "gk", "type": "player", "x": 44, "y": 16, "label": "GK", "color": "#22c55e", "rotation": 0, "size": 1}, {"id": "s", "type": "player", "x": 40, "y": 55, "label": "S", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "c1", "type": "cone", "x": 30, "y": 50, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c2", "type": "cone", "x": 40, "y": 50, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c3", "type": "cone", "x": 50, "y": 50, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c4", "type": "cone", "x": 60, "y": 50, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c5", "type": "cone", "x": 70, "y": 50, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "b1", "type": "ball", "x": 42, "y": 14, "color": "#f5f5f5", "rotation": 0, "size": 1}]$JSON$::jsonb, $JSON$[{"id": "a1", "type": "arrow-solid", "geometry": {"from": {"x": 40, "y": 55}, "to": {"x": 42, "y": 14}}, "style": {"color": "#fbbf24"}}, {"id": "t1", "type": "text", "geometry": {"x": 50, "y": 88, "text": "Catch at highest point"}}]$JSON$::jsonb);
INSERT INTO drill_frames (drill_id, position, duration_ms, notes, objects, annotations) VALUES ('2a26d6fc-934b-41e8-b44a-6bd14731e73f', 4, 2400, 'Frame 4 — GK rolls ball back, resets to centre of goal. Server cycles through cones every 6 reps so the angle changes.', $JSON$[{"id": "g1", "type": "goal-full", "x": 50, "y": 8, "color": "#ffffff", "rotation": 0, "size": 1}, {"id": "gk", "type": "player", "x": 50, "y": 18, "label": "GK", "color": "#22c55e", "rotation": 0, "size": 1}, {"id": "s", "type": "player", "x": 50, "y": 60, "label": "S", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "c1", "type": "cone", "x": 30, "y": 50, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c2", "type": "cone", "x": 40, "y": 50, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c3", "type": "cone", "x": 50, "y": 50, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c4", "type": "cone", "x": 60, "y": 50, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c5", "type": "cone", "x": 70, "y": 50, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "b1", "type": "ball", "x": 47, "y": 60, "color": "#f5f5f5", "rotation": 0, "size": 1}, {"id": "b2", "type": "ball", "x": 53, "y": 60, "color": "#f5f5f5", "rotation": 0, "size": 1}]$JSON$::jsonb, $JSON$[{"id": "t1", "type": "text", "geometry": {"x": 50, "y": 14, "text": "Reset → centre of goal"}}, {"id": "t2", "type": "text", "geometry": {"x": 50, "y": 88, "text": "Server moves cone every 6 reps"}}]$JSON$::jsonb);